def min_swaps(nums):
    n = len(nums)
    k = sum(nums)
    if k == 0 or k == n:
        return 0
    best = float('inf')
    for start in range(n):
        zeros = 0
        for offset in range(k):
            if nums[(start + offset) % n] == 0:      # wrap the index using modulo n
                zeros += 1
        best = min(best, zeros)
    return best

