def min_swaps(nums):
    n = len(nums)
    k = sum(nums)
    if k == 0 or k == n:
        return 0
    zeros = sum(1 for i in range(k) if nums[i] == 0)   # first window, counted once
    best = zeros
    for start in range(1, n):
        leaving = start - 1
        entering = (start + k - 1) % n                    # wrap using modulo n
        if nums[leaving] == 0:
            zeros -= 1
        if nums[entering] == 0:
            zeros += 1
        best = min(best, zeros)
    return best

